"use client";

import { DEFAULT_SHIMMER } from "./animated-headline/constants";
import { RotateAppearance } from "./animated-headline/rotate-appearance";
import { RotateWord } from "./animated-headline/rotate-word";
import { usePrefersReducedMotion } from "./animated-headline/use-prefers-reduced-motion";

export { RotateAppearance, type RotateAppearanceProps } from "./animated-headline/rotate-appearance";
export { RotateWord, type RotateWordProps } from "./animated-headline/rotate-word";
export { ShinyUnderline, type ShinyUnderlineProps } from "./animated-headline/shiny-underline";

export interface AnimatedHeadlineProps {
  /** The fixed words before the rotating slot, e.g. "Engineering things people love to". */
  prefix: string;
  /** The words the last slot cycles through, e.g. ["build", "design", "ship", "use"]. */
  words: string[];
  /** How long each rotating word is held, in ms. Default 2000 (x.ai's beat). */
  dwellMs?: number;
  /** Per-word flip-up stagger, in ms. Default 110. */
  staggerMs?: number;
  /** Colour stops for the shimmer band. Defaults to x.ai's indigo to yellow rainbow. */
  shimmerColors?: string[];
  className?: string;
}

export function AnimatedHeadline({
  prefix,
  words,
  dwellMs = 2000,
  staggerMs = 110,
  shimmerColors = DEFAULT_SHIMMER,
  className = "",
}: AnimatedHeadlineProps) {
  const reduceMotion = usePrefersReducedMotion();
  const prefixWords = prefix.trim().split(/\s+/).filter(Boolean);
  const revealMs = (prefixWords.length + 1) * staggerMs + 900;

  return (
    <h2
      data-slot="animated-headline"
      className={`flex flex-wrap items-baseline gap-x-[0.28em] gap-y-2 font-medium leading-[1.18] tracking-tight ${className}`}
      style={{ perspective: 1200 }}
    >
      {prefixWords.map((word, index) => (
        <RotateAppearance key={`${word}-${index}`} delayMs={index * staggerMs} reduceMotion={reduceMotion}>
          {word}
        </RotateAppearance>
      ))}

      <RotateAppearance
        className="relative inline-block align-baseline"
        delayMs={prefixWords.length * staggerMs}
        reduceMotion={reduceMotion}
      >
        <RotateWord
          words={words}
          dwellMs={dwellMs}
          startDelayMs={revealMs}
          reduceMotion={reduceMotion}
          shimmerColors={shimmerColors}
        />
      </RotateAppearance>
    </h2>
  );
}

export default AnimatedHeadline;

export const DEFAULT_SHIMMER = ["#6366f1", "#a855f7", "#ec4899", "#f97316", "#eab308"];

export const UNDERLINE_SHIMMER_MS = 2500;

export const WORD_SWAP_MS = 420;

"use client";

import { useEffect, useState } from "react";

export function usePrefersReducedMotion() {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    setPrefersReducedMotion(query.matches);

    const handleChange = () => setPrefersReducedMotion(query.matches);
    query.addEventListener("change", handleChange);

    return () => query.removeEventListener("change", handleChange);
  }, []);

  return prefersReducedMotion;
}

"use client";

import { type CSSProperties, type ReactNode } from "react";

import { usePrefersReducedMotion } from "./use-prefers-reduced-motion";

export interface RotateAppearanceProps {
  children: ReactNode;
  className?: string;
  delayMs?: number;
  reduceMotion?: boolean | null;
  style?: CSSProperties;
}

export function RotateAppearance({
  children,
  className = "inline-block",
  delayMs = 0,
  reduceMotion,
  style,
}: RotateAppearanceProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const shouldReduceMotion = reduceMotion ?? prefersReducedMotion;

  return (
    <span
      data-slot="rotate-appearance"
      className={className}
      style={{
        transformOrigin: "50% 100%",
        animation: shouldReduceMotion ? undefined : "hero-word-reveal 0.72s cubic-bezier(0.2, 0.72, 0.2, 1) both",
        animationDelay: shouldReduceMotion ? undefined : `${delayMs}ms`,
        ...style,
      }}
    >
      {children}
    </span>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import { DEFAULT_SHIMMER, WORD_SWAP_MS } from "./constants";
import { ShinyUnderline } from "./shiny-underline";
import { usePrefersReducedMotion } from "./use-prefers-reduced-motion";

export interface RotateWordProps {
  words: string[];
  dwellMs?: number;
  startDelayMs?: number;
  reduceMotion?: boolean | null;
  className?: string;
  shimmerColors?: string[];
  showUnderline?: boolean;
}

export function RotateWord({
  words,
  dwellMs = 2000,
  startDelayMs = 0,
  reduceMotion,
  className = "",
  shimmerColors = DEFAULT_SHIMMER,
  showUnderline = true,
}: RotateWordProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const shouldReduceMotion = reduceMotion ?? prefersReducedMotion;
  const [index, setIndex] = useState(0);
  const [exitingWord, setExitingWord] = useState<string>();
  const [hasRotated, setHasRotated] = useState(false);
  const word = words[index] ?? "";

  const measureRef = useRef<HTMLSpanElement>(null);
  const [width, setWidth] = useState<number>();
  const enterAnimation = shouldReduceMotion ? undefined : "hero-word-enter 0.42s cubic-bezier(0.7, 0, 0.3, 1) both";
  const exitAnimation = shouldReduceMotion ? undefined : "hero-word-exit 0.42s cubic-bezier(0.7, 0, 0.3, 1) both";

  useEffect(() => {
    if (measureRef.current) setWidth(measureRef.current.offsetWidth);
  }, [word]);

  useEffect(() => {
    if (index >= words.length) setIndex(0);
  }, [index, words.length]);

  useEffect(() => {
    if (shouldReduceMotion || words.length <= 1) return;

    const clearExitIdRef: { current?: number } = {};
    let rotateId: number | undefined;

    const rotate = () => {
      setIndex((currentIndex) => {
        const currentWord = words[currentIndex] ?? "";
        const nextIndex = (currentIndex + 1) % words.length;

        setExitingWord(currentWord);
        setHasRotated(true);
        if (clearExitIdRef.current) window.clearTimeout(clearExitIdRef.current);
        clearExitIdRef.current = window.setTimeout(() => setExitingWord(undefined), WORD_SWAP_MS);

        return nextIndex;
      });
    };

    const startId = window.setTimeout(() => {
      rotateId = window.setInterval(rotate, dwellMs);
    }, startDelayMs);

    return () => {
      window.clearTimeout(startId);
      if (rotateId) window.clearInterval(rotateId);
      if (clearExitIdRef.current) window.clearTimeout(clearExitIdRef.current);
    };
  }, [shouldReduceMotion, words, dwellMs, startDelayMs]);

  return (
    <span
      data-slot="rotate-word"
      data-reduce-motion={shouldReduceMotion ? "" : undefined}
      className={`relative inline-block align-baseline ${className}`}
      style={{
        width,
        transition: shouldReduceMotion ? undefined : "width 0.4s cubic-bezier(0.2, 0.72, 0.2, 1)",
      }}
    >
      <span ref={measureRef} aria-hidden className="invisible whitespace-nowrap">
        {word}
      </span>

      <span data-slot="rotate-word-viewport" className="absolute inset-0 overflow-hidden">
        {exitingWord && exitingWord !== word ? (
          <span
            data-slot="rotate-word-item"
            data-state="exit"
            className="absolute inset-0 whitespace-nowrap"
            style={{ animation: exitAnimation }}
          >
            {exitingWord}
          </span>
        ) : null}

        <span
          key={word}
          data-slot="rotate-word-item"
          data-state={hasRotated ? "enter" : "settled"}
          className="absolute inset-0 whitespace-nowrap"
          style={{ animation: hasRotated ? enterAnimation : undefined }}
        >
          {word}
        </span>
      </span>

      {showUnderline ? (
        <ShinyUnderline replayKey={index} shimmerColors={shimmerColors} reduceMotion={shouldReduceMotion} />
      ) : null}
    </span>
  );
}

"use client";

import { type Key } from "react";

import { DEFAULT_SHIMMER, UNDERLINE_SHIMMER_MS } from "./constants";
import { usePrefersReducedMotion } from "./use-prefers-reduced-motion";

export interface ShinyUnderlineProps {
  replayKey?: Key;
  shimmerColors?: string[];
  shimmerDurationMs?: number;
  repeat?: boolean;
  reduceMotion?: boolean | null;
  className?: string;
}

export function ShinyUnderline({
  replayKey,
  shimmerColors = DEFAULT_SHIMMER,
  shimmerDurationMs = UNDERLINE_SHIMMER_MS,
  repeat = false,
  reduceMotion,
  className = "",
}: ShinyUnderlineProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const shouldReduceMotion = reduceMotion ?? prefersReducedMotion;
  const grey = "color-mix(in oklch, currentColor 28%, transparent)";
  const rainbow = shimmerColors.map((color, index) => `${color} ${40 + index * 5}%`).join(", ");
  const underlineGradient = `linear-gradient(90deg, ${grey} 0%, ${grey} 35%, ${rainbow}, ${grey} 65%, ${grey} 100%)`;
  const revealAnimation = shouldReduceMotion ? undefined : "hero-underline-reveal 0.36s ease-out 0.5s both";
  const shimmerAnimation = shouldReduceMotion
    ? undefined
    : `hero-underline-shimmer ${shimmerDurationMs}ms linear ${repeat ? "infinite" : ""}`;

  return (
    <span
      aria-hidden
      data-slot="shiny-underline"
      className={`pointer-events-none absolute -bottom-[0.08em] left-0 right-0 h-[3px] origin-left overflow-hidden rounded-full ${className}`}
      style={{ animation: revealAnimation }}
    >
      <span
        key={replayKey}
        data-slot="shiny-underline-shimmer"
        className="absolute inset-0 rounded-full"
        style={{
          backgroundImage: underlineGradient,
          backgroundSize: "400% 100%",
          backgroundPosition: "0% 50%",
          animation: shimmerAnimation,
        }}
      />
    </span>
  );
}
